# The hand layer of the Kanto 151 move catalog (energy v2), read by gen.py. Every game move
# a Kanto species can learn is converted from the game data automatically; an entry here
# overrides the conversion for that move (only the fields given), or adds a move the games
# don't have (Dodge, Ground Pound). The TCG signature moves live in tcg_sigs.py.
# m(id, name, mtype, category, role, chips, **kw)
#   chips: 1..3 for a fixed cost, or "F<n>" for a finisher (all chips, at least n)
#   kw: acc, pri, eff (space separated tags), anim, desc, typed (typed chips in the cost),
#       hits (states it hits: underground airborne underwater), two (two-phase state),
#       react (reaction kind), fixed (fixed damage: a number, "level" or "half_hp"),
#       combo (dict), src ("game" | "tcg" | "anime" | "new"), gen (the game generation it debuts in)

MOVES = []

def m(id, name, mtype, cat, role, chips, **kw):
    MOVES.append(dict(id=id, name=name, mtype=mtype, cat=cat, role=role, chips=chips, **kw))

O, R, T, D, U = "offense", "reaction", "two_phase", "disruption", "utility"
P, S, X = "physical", "special", "status"

